WITH with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY MONTH(last_restock), product_id ORDER BY quantity DESC, id) AS row_seq, LAG(quantity, 1) OVER (PARTITION BY product_id ORDER BY quantity, id) AS prev_quantity FROM inventory) SELECT product_id, store_id, COUNT(DISTINCT store_id) AS distinct_store_ids, COUNT(DISTINCT product_id) AS distinct_product_ids, COUNT(*) AS cnt, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles FROM with_windows GROUP BY product_id, store_id ORDER BY cnt NULLS LAST;
